// Generated by philote from endpoint complete. Do not edit.
import type { Hono } from "hono";
import { find } from "../runtime/store.js";
import { StepError } from "../runtime/step.js";
import { validate } from "../runtime/validate.js";
import type { Status, Project, Task } from "../types.js";
import { finishTask } from "../steps/finish_task.js";

export function routeComplete(app: Hono): void {
  app.post("/complete", async (ctx) => {
    const checked = validate(
      {
        task: { kind: "ref", table: "Task" },
      },
      await ctx.req.json().catch(() => undefined),
      false,
    );
    if (checked.issues.length) {
      return ctx.json({ error: "invalid_input", issues: checked.issues }, 400);
    }
    try {
      const task = find("Task", checked.values.task as string) as Task;
      const done = await finishTask(task);
      return ctx.json(done);
    } catch (error) {
      if (error instanceof StepError) {
        return ctx.json({ error: error.code }, error.code === "not_found" ? 404 : 422);
      }
      throw error;
    }
  });
}
